from functools import lru_cache

@lru_cache(maxsize=None)
def fib_memoized(n):
    if n < 2:
        return n
    return fib_memoized(n - 1) + fib_memoized(n - 2)

if __name__ == "__main__":
    print([fib_memoized(i) for i in range(10)])

